const src = $input.first().json;
const taskId = src.id || src.clickup_task_id || src.taskId || null;
const atts = Array.isArray(src.attachments) ? src.attachments : [];
const out = [];
let i = 0;
for (const a of atts) {
  const title = a.title || '';
  const ext = String(a.ext || a.extension || title.split('.').pop() || '').toLowerCase();
  out.push({ json: {
    clickup_task_id: taskId,
    att_id: a.att_id || a.id || null,
    title: title || ('attachment.' + ext),
    ext,
    mime: String(a.mime || a.mimetype || '').toLowerCase(),
    url: a.url || a.url_w_query || '',
    order: (a.order !== undefined && a.order !== null ? a.order : i)
  }});
  i++;
}
if (out.length === 0) {
  // No attachments: emit a single passthrough sentinel so the chain still
  // reaches Aggregate Blocks. A zero-item Explode would skip every downstream
  // node, return nothing, and silently null the whole pipeline (no reply/status/cost).
  out.push({ json: { clickup_task_id: taskId, _passthrough: true, order: -1 } });
}
return out;

const m = $json;
if (m._passthrough) {
  // No-attachment passthrough: emit a block-less item so Aggregate Blocks runs
  // (its filter drops items without a `block`) and returns { blocks: [], ... }.
  return { json: { clickup_task_id: m.clickup_task_id } };
}
const hasRef = !!m.url;
const block = hasRef
  ? { type: 'image', order: m.order, ref: m.url, mime: m.mime || 'image/*', source: 'input', source_ref: m.att_id, alt: m.title }
  : { type: 'text', order: m.order, md: '[BRAK: image_ref_missing ' + m.title + ']' };
return { json: {
  block,
  clickup_task_id: m.clickup_task_id,
  title: m.title,
  needs_alert: !hasRef,
  has_embedded: false,
  warn_source: hasRef ? '' : 'multimodal/image-ref-missing',
  err: hasRef ? '' : 'image attachment missing url'
} };

let meta;
try { meta = $('Explode Zip Entries').item.json; } catch (e) { try { meta = $('Explode Attachments').item.json; } catch (e2) { meta = {}; } }
if (!meta || meta.order === undefined) { meta = { order: 0, title: (meta && meta.title) || 'unknown', clickup_task_id: (meta && meta.clickup_task_id) || null }; }
const doc = ($json && $json.document) || {};
const md = doc.md_content || '';
const ok = !!md;
let err = '';
if (!ok) {
  if ($json && $json.error) { err = $json.error.message || (typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error)); }
  else if ($json && $json.status && $json.status !== 'success') { err = 'docling status=' + $json.status; }
  else { err = 'no md_content'; }
}
const block = ok
  ? { type: 'text', order: meta.order, md }
  : { type: 'text', order: meta.order, md: '[BRAK: extraction_failed ' + meta.title + ']' };
return { json: {
  block,
  clickup_task_id: meta.clickup_task_id,
  title: meta.title,
  needs_alert: !ok,
  has_embedded: ok && (md.includes('<!-- image -->') || md.includes('<!-- missing-image -->')),
  warn_source: !ok ? 'multimodal/extraction-failed' : '',
  err: err || ''
} };

const rows = $input.all().map(i => i.json).filter(j => j && j.block);
const blocks = rows.map(j => j.block).sort((a, b) => (a.order || 0) - (b.order || 0));
const warnings = [];
for (const j of rows) {
  if (j.needs_alert) warnings.push({ source: j.warn_source || 'multimodal/extraction-failed', title: j.title, err: j.err || 'unknown' });
  else if (j.has_embedded) warnings.push({ source: 'multimodal/embedded-image-skipped', title: j.title });
}
let taskId = null;
try { taskId = $('When Called').first().json.clickup_task_id; } catch (e) {}
if (!taskId) { try { taskId = $('Form Trigger').first().json.taskId; } catch (e) {} }
if (!taskId) { const f = rows.find(j => j.clickup_task_id); taskId = f ? f.clickup_task_id : null; }
return [{ json: { blocks, clickup_task_id: taskId, warnings } }];

const m = $input.item.json || {};
const b = $input.item.binary;
const taskId = m.clickup_task_id;
const attId = m.att_id;
const mime = m.mime || (b && b.data && b.data.mimeType) || 'image/jpeg';
const safe = String(attId == null ? '' : attId).replace(/[^a-zA-Z0-9._-]/g, '_');
return { json: { clickup_task_id: taskId, att_id: attId, title: m.title, order: m.order, mime: mime, storage_path: taskId + '/' + safe }, binary: b };

const k = $('Zip Image Key').item.json;
const r = $json || {};
const signed = r.signedURL || (r.body && r.body.signedURL) || '';
const HOST = 'https://hkeslnosxibeuesxndnz.supabase.co';
const ref = signed ? (HOST + '/storage/v1' + signed) : '';
return { json: { clickup_task_id: k && k.clickup_task_id, att_id: k && k.att_id, title: k && k.title, order: k && k.order, mime: k && k.mime, ref: ref, stored: !!ref } };

const IMG_EXT = ['png','jpg','jpeg','gif','webp','bmp','svg','tiff','tif','heic','heif'];
let cfg = {};
try { cfg = $('Lookup File Processing Config').first().json || {}; } catch (e) { cfg = {}; }
const maxEntries = Number(cfg.zip_max_entries) || 50;
const maxFileMb = Number(cfg.zip_max_file_mb) || 25;
const maxTotalMb = Number(cfg.zip_max_total_uncompressed_mb) || 250;
const MB = 1024 * 1024;
const items = $input.all();
const out = [];
for (let z = 0; z < items.length; z++) {
  const bin = items[z].binary || {};
  const failed = !!(items[z].json && items[z].json.error);
  let parent = {};
  try { parent = $('Explode Attachments').itemMatching(z).json || {}; } catch (e) { try { parent = $('Explode Attachments').first().json || {}; } catch (e2) { parent = {}; } }
  const taskId = parent.clickup_task_id || (items[z].json && items[z].json.clickup_task_id) || null;
  const parentAttId = parent.att_id || 'zip';
  const parentOrder = (parent.order !== undefined && parent.order !== null) ? Number(parent.order) : 0;
  const parentTitle = parent.title || 'archive.zip';
  const keys = Object.keys(bin).sort((a, b) => {
    const na = parseInt(String(a).replace(/\D+/g, ''), 10);
    const nb = parseInt(String(b).replace(/\D+/g, ''), 10);
    return (isNaN(na) ? 0 : na) - (isNaN(nb) ? 0 : nb);
  });
  if (failed || keys.length === 0) {
    out.push({ json: { clickup_task_id: taskId, att_id: parentAttId + ':x', title: parentTitle, order: parentOrder + 0.001, route: 'drop', drop_reason: 'zip_extraction_failed', warn_source: 'multimodal/zip-extraction-failed' }, pairedItem: z });
    continue;
  }
  let accepted = 0;
  let totalBytes = 0;
  for (let i = 0; i < keys.length; i++) {
    const prop = keys[i];
    const meta = bin[prop] || {};
    const name = meta.fileName || prop;
    const lname = String(name).toLowerCase();
    const base = lname.split('/').pop();
    const ext = String(meta.fileExtension || (base.indexOf('.') >= 0 ? base.split('.').pop() : '')).toLowerCase();
    const mime = String(meta.mimeType || '').toLowerCase();
    const order = parentOrder + (i + 1) / 1000;
    const attId = parentAttId + ':' + i;
    if (lname.endsWith('/') || lname.indexOf('__macosx') >= 0 || base.charAt(0) === '.' || base === '') continue;
    if (ext === 'zip' || ((mime === 'application/zip' || mime === 'application/x-zip-compressed') && (ext === '' || ext === 'zip'))) {
      out.push({ json: { clickup_task_id: taskId, att_id: attId, title: name, order: order, route: 'drop', drop_reason: 'nested_zip', warn_source: 'multimodal/zip-nested-skipped' }, pairedItem: z });
      continue;
    }
    if (accepted >= maxEntries) {
      out.push({ json: { clickup_task_id: taskId, att_id: attId, title: name, order: order, route: 'drop', drop_reason: 'too_many_entries', warn_source: 'multimodal/zip-too-large' }, pairedItem: z });
      continue;
    }
    let bytes = 0;
    try {
      const h = (typeof $helpers !== 'undefined' && $helpers) ? $helpers : ((typeof this !== 'undefined' && this && this.helpers) ? this.helpers : null);
      if (h && h.getBinaryDataBuffer) { const buf = await h.getBinaryDataBuffer(z, prop); bytes = buf.length; }
    } catch (e) { bytes = 0; }
    if (!bytes) {
      const fsz = meta.fileSize;
      if (typeof fsz === 'number') bytes = fsz;
      else if (typeof fsz === 'string') { const mm = fsz.trim().match(/^([\d.]+)\s*([kKmMgG]?)/); if (mm) { const n = parseFloat(mm[1]); const u = (mm[2] || '').toLowerCase(); bytes = n * (u === 'g' ? 1073741824 : u === 'm' ? 1048576 : u === 'k' ? 1024 : 1); } }
    }
    if (bytes > maxFileMb * MB) {
      out.push({ json: { clickup_task_id: taskId, att_id: attId, title: name, order: order, route: 'drop', drop_reason: 'oversize_' + Math.round(bytes / MB) + 'mb', warn_source: 'multimodal/zip-too-large' }, pairedItem: z });
      continue;
    }
    if (totalBytes + bytes > maxTotalMb * MB) {
      out.push({ json: { clickup_task_id: taskId, att_id: attId, title: name, order: order, route: 'drop', drop_reason: 'over_total_uncompressed', warn_source: 'multimodal/zip-too-large' }, pairedItem: z });
      continue;
    }
    accepted++;
    totalBytes += bytes;
    const isImage = mime.indexOf('image/') === 0 || IMG_EXT.indexOf(ext) >= 0;
    out.push({ json: { clickup_task_id: taskId, att_id: attId, title: name, ext: ext, mime: mime, order: order, source: 'zip', route: isImage ? 'image' : 'document' }, binary: { data: bin[prop] }, pairedItem: z });
  }
}
return out;

const m = $json;
const ok = !!m.stored && !!m.ref;
const block = ok
  ? { type: 'image', order: m.order, ref: m.ref, mime: m.mime || 'image/*', source: 'input', source_ref: m.att_id, alt: m.title }
  : { type: 'text', order: m.order, md: '[BRAK: zip_image_store_failed ' + (m.title || '') + ']' };
return { json: { block: block, clickup_task_id: m.clickup_task_id, title: m.title, needs_alert: !ok, has_embedded: false, warn_source: ok ? '' : 'multimodal/zip-image-store-failed', err: ok ? '' : 'zip-inner image upload/sign failed' } };

const m = $json;
const reason = m.drop_reason || 'zip_entry_dropped';
return { json: { block: { type: 'text', order: m.order, md: '[BRAK: ' + reason + ' ' + (m.title || '') + ']' }, clickup_task_id: m.clickup_task_id, title: m.title, needs_alert: true, has_embedded: false, warn_source: m.warn_source || 'multimodal/zip-dropped', err: reason } };

const item = $input.item;
if (item.binary && item.binary.data) {
  const b = item.binary.data;
  let title = '';
  try { title = String($('Explode Attachments').item.json.title || ''); } catch (e) { title = ''; }
  if (!b.fileName || !/\.zip$/i.test(b.fileName)) {
    b.fileName = /\.zip$/i.test(title) ? title : 'archive.zip';
  }
  b.fileExtension = 'zip';
  b.mimeType = 'application/zip';
}
return item;
